    'Register'=>'ලියාපදිංචි වන්න',
    'RegisterSimpleRisk'=>'සරල අවදානම් ලියාපදිංචි කරන්න',
    'RegistrationText'=>'ලියාපදිංචි වූ SimpleRisk අවස්ථා සඳහා උත්ශ්‍රේණිගත කිරීම සහ ආරක්‍ෂිත පාලන රාමුව (SCF) අමතර කොටස් වෙත ප්‍රවේශය ලබා දෙනු ලැබේ. Upgrade Extra මඟින් බොත්තමක් ක්ලික් කිරීමෙන් ඔබේ SimpleRisk අවස්ථාව උපස්ථ කිරීමට සහ උත්ශ්‍රේණි කිරීමට හැකියාව ලබා දේ. Secure Controls Framework (SCF) Extra මගින් SimpleRisk Governance ක්‍රියාකාරීත්වයට ඒකාබද්ධ වූ පොදු පාලන රාමුවක් සපයයි. SimpleRisk ලියාපදිංචි කිරීමෙන් පසු, ඔබේ ලියාපදිංචි තොරතුරු SimpleRisk විසින් සත්කාරකත්වය සපයන සේවාදායකයකට යවනු ලැබේ. සපයා ඇති ලියාපදිංචි තොරතුරු SimpleRisk විසින් නව නිකුතු සහ ආරක්ෂක යාවත්කාලීන පිළිබඳව පාරිභෝගිකයින්ට දැනුම් දීමට භාවිතා කරනු ඇත. SimpleRisk ලියාපදිංචි කිරීමේ ක්‍රියාව ඔබව අපගේ අලෙවිකරණ සන්නිවේදනයන් වෙත තෝරා ගනු ඇත, නමුත් ඔබට මෙම සන්නිවේදනයේ ඇති දායකත්වයෙන් ඉවත් වීමේ සබැඳිය භාවිතයෙන් ඕනෑම අවස්ථාවක ඉවත් විය හැක. SimpleRisk අපගේ ගනුදෙනුකරුවන්ගේ පෞද්ගලිකත්වයට ගරු කරන අතර SimpleRisk ලියාපදිංචි කිරීමේ ක්‍රියාවලිය හරහා අපට ලබා දෙන තොරතුරු කිසි විටෙකත් තෙවන පාර්ශවයකට විකුණනු නොලැබේ.',
