    'ConditionMessageForDigit' => 'මුරපදයේ ඉලක්කම් අඩංගු විය යුතුය.',
    'ConditionMessageForSpecialchar' => 'මුරපදයේ විශේෂ අක්ෂරයක් අඩංගු විය යුතුය.',
