    'HideRiskScoreOverTime' => 'කාලයත් සමඟ අවදානම් ලකුණු සඟවන්න',
    'ReviewRegularlyHelp' => 'පහත දැක්වෙන්නේ, සමාලෝචනය නොකළ, අතීත නියමිත හා ඊළඟ සමාලෝචන දිනය අනුව වර්ග කර ඇති සියලුම අවදානම් ලැයිස්තුවයි',
    'RiskScoringHistory' => 'අවදානම් ලකුණු ඉතිහාසය',
    'RiskAddPermissionMessage' => 'ඔබට නව අවදානම් ඉදිරිපත් කිරීමට අවසර නැත. ඔබ ඉදිරිපත් කිරීමට උත්සාහ කරන ඕනෑම අවදානමක් වාර්තා නොකෙරේ. ඔබට මෙම පණිවිඩය වැරදීමකින් ලැබී ඇති බව ඔබට හැඟේ නම් කරුණාකර පරිපාලකවරයෙකු අමතන්න.',
    'SubjectRiskCannotBeEmpty' => 'අවදානමක විෂය හිස් විය නොහැක',
    'InvalidRiskID' => 'අවලංගු අවදානම් හැඳුනුම්පත',
    'Success' => 'සාර්ථකත්වය',
    'RiskUpdatePermissionMessage' => 'අවදානම් වෙනස් කිරීමට ඔබට අවසර නැත. ඔබ වෙනස් කිරීමට උත්සාහ කරන ඕනෑම අවදානම් වාර්තා නොකෙරේ. ඔබට මෙම පණිවිඩය වැරදීමකින් ලැබී ඇති බව ඔබට හැඟේ නම් කරුණාකර පරිපාලකවරයෙකු අමතන්න.',
    'RiskReviewPermission' => '$risk_level මට්ටමේ අවදානම් සමාලෝචනය කිරීමට ඔබට අවසර නැත. ඔබ ඉදිරිපත් කිරීමට උත්සාහ කරන ඕනෑම සමාලෝචනයක් වාර්තා නොකෙරේ. ඔබට මෙම පණිවිඩය වැරදීමකින් ලැබී ඇති බව ඔබට හැඟේ නම් කරුණාකර පරිපාලක අමතන්න.',
    'DateAndTime' => 'දිනය සහ වේලාව',
    'mCryptWarning' => 'ගුප්තකේතන අමතර නිසියාකාරව වැඩ කිරීම සඳහා "mcrypt" දිගුව ස්ථාපනය කළ යුතුය. ඉදිරියට යාමට කරුණාකර එය ස්ථාපනය කරන්න.',
    'APIInCompatibleWithEncryptionLevel' => 'ගුප්තකේතනය කළ දත්ත ගබඩාවේ අමතර පරිශීලක සංකේතාංකන මට්ටමට API අනුකූල නොවේ.',
    'UnauthenticatedAccessInAPI' => 'සත්‍යාපනය නොකළ ප්‍රවේශය. SimpleRisk API භාවිතා කිරීමට කරුණාකර ලොග් වන්න හෝ යතුරක් සපයන්න.',
    'ResetPasswordMessageInUserLevelEncryption' => 'මෙම පරිශීලකයා පරිශීලක මට්ටමේ සංකේතනයක සිටින බැවින් ඔබට මුරපදය නැවත සැකසිය නොහැක. කරුණාකර පරිපාලක අමතන්න.',
