    'PasswordNoLongerUse' => 'මුරපද ඉතිහාසය සක්‍රීය කර ඇති අතර මෙම මුරපදය දැනටමත් භාවිතා කර ඇත. කරුණාකර වෙනත් මුරපදයක් උත්සාහ කරන්න.',
