    'AffectedAssetsWidgetNoDropdownPlaceholder' => 'වත්කම් නාමයක් එක් කරන්න',
    'AffectedAssetsWidgetInstructions' => 'වත්කම් හෝ වත්කම් කණ්ඩායමක් තෝරන්න. ලැයිස්තුවට එහි නම එකතු කිරීමෙන් ඔබට නව වත්කමක් නිර්මාණය කළ හැකිය.',
