    'ImportAssetGroupAddFailed' => '"{$asset_group_name}" නම් වූ වත්කම් සමූහය එක් කිරීමට අපොහොසත් විය.',
    'ImportAssetGroupAddNameTaken' => 'නම දැනටමත් භාවිතයේ පවතින බැවින් "{$asset_group_name}" නම් වූ වත්කම් සමූහය එක් කිරීමට අපොහොසත් විය.',
