    'ImportAssetGroupUpdateFailed' => '"{$asset_group_name}" නම් වූ වත්කම් සමූහය යාවත්කාලීන කිරීමට අපොහොසත් විය.',
    'ImportAssetGroupUpdateNameTaken' => 'නම දැනටමත් භාවිතයේ පවතින බැවින් "{$asset_group_name}" නම් වූ වත්කම් සමූහය යාවත්කාලීන කිරීමට අපොහොසත් විය.',
    'GroupMaximumQuantitativeLoss' => 'සමූහයේ උපරිම ප්‍රමාණාත්මක පාඩුව',
    'AssetGroupRisk' => 'වත්කම් සමූහයේ අවදානම',
    'NonMitigationNotificationEamilDescription' => 'ඔබට මෙම පණිවිඩය ලැබෙන්නේ ඔබ ඉදිරිපත් කරන්නා, හිමිකරු, හිමිකරුගේ කළමනාකරු, කණ්ඩායමට අයත් වීම හෝ අවම කිරීමකින් තොරව පහත සඳහන් අවදානම් සමඟ සම්බන්ධිත අතිරේක පාර්ශවකරුවෙකු වීම නිසාය. අවම කිරීමක් සැලසුම් කරන තුරු ඔබට දිගටම විද්‍යුත් තැපැල් මතක් කිරීම් ලැබෙනු ඇත.',
    'Manager' => 'කළමනාකරු',
    'ErrorAssetAlreadyExistsAsVerified' => '"{$asset_name}" වත්කම දැනටමත් පවතී, නමුත් තවම සත්‍යාපනය කර නොමැත. කරුණාකර ඔබේ වත්කම් කළමනාකරණ පිටුව පරීක්ෂා කරන්න හෝ පරිපාලකයෙකු අමතන්න.',
    'NoPermissionForAssetAssetGroupList' => 'පවතින වත්කම් ලැයිස්තුව බැලීමට, අවදානම්, වත්කම් හෝ තක්සේරු කළමණාකරනය සඳහා ඔබට අවසර අවශ්‍ය වේ.',
    'NoPermissionForClosingRisks'=>'අවදානම් වැසීමට ඔබට අවසර නැත.',
