    'UpdateInstalledExtrasOutOfDate' => 'අමතර (ය) යල්පැන ඇති. පහත සඳහන් අමතර (ය) යාවත්කාලීන කළ යුතුය: "{$extrasToUpdate}"',
    'UpdateInstalledExtrasUpToDate' => 'අමතර යාවත්කාලීන වේ.',
