    'JiraInstanceURLIsRequired' => 'ජිරා උදාහරණ URL අවශ්‍යයි!',
    'JiraUserEmailIsRequired' => 'ජිරා පරිශීලකයාගේ විද්‍යුත් තැපෑල අවශ්‍යයි!',
    'JiraUserAPIKeyIsRequired' => 'ජිරා පරිශීලකයාගේ API යතුර අවශ්‍යයි!',
    'JiraInstanceURLIsInvalid' => 'අවලංගු ජිරා උදාහරණ URL හෝ ජිරා උදාහරණය අක්‍රීයයි!',
    'JiraServerInfoNotAccessible' => 'ජිරා උදාහරණයේ සේවාදායක තොරතුරු අන්ත ලක්ෂ්‍යයට ප්‍රවේශ විය නොහැක, සේවාදායකයා වෙබ් හූක් සඳහා සහය දක්වයිද යන්න තීරණය කළ නොහැක.',
    'JiraServerInfoInvalidOrMissingBuildNumber' => 'ජිරා නිදර්ශන තැනීමේ අංකය අවලංගු හෝ නැතිවී ඇත, සේවාදායකයා වෙබ් හූක් සඳහා සහය දක්වයිද යන්න තීරණය කළ නොහැක.',
    'JiraWebhookNotSupported' => 'වින්‍යාස කරන ලද ජිරා උදාහරණය වෙබ් හූක් සඳහා සහය නොදක්වයි. වෙබ් හූක් සඳහා සහය දක්වන අවම අනුවාදය 5.2 (ගොඩනැගීමේ අංකය 810+) වේ.',
    'JiraWebhookNotSupportedOnHttp' => 'මෙම අමතර භාවිතා කිරීමට ඔබට ඔබේ සරල අවදානම් අවස්ථාව https මත ධාවනය කළ යුතුය.',
    'JiraConnectionSettingsWarning' => 'ඔබගේ සම්බන්ධතා සැකසුම් අවලංගුය. සමමුහුර්තකරණය සහ සමමුහුර්තකරණ සැකසුම් වලට ප්‍රවේශ වීම අක්‍රීය කර ඇත.',
    'JiraConnectionSettingsSuccess' => 'ඔබගේ සම්බන්ධතා සැකසුම් වලංගු වේ. සමමුහුර්තකරණය සක්‍රීය කර ඇත.',
    'JiraWebhookSetupFailed' => 'වෙබ්හුක් සැකසීම අසාර්ථක විය. කරුණාකර ඔබගේ සම්බන්ධතා සැකසුම් පරීක්ෂා කරන්න.',
    'JiraWebhookSetupSuccess' => 'වෙබ්හුක් සාර්ථකව සැකසීය.',

    'JiraProjectSynchronizationSettings' => 'ව්‍යාපෘති සමමුහුර්ත සැකසුම්',
    'JiraFailedGetIssueTypes' => 'ගැටළු වර්ග ලබා ගැනීමට අපොහොසත් විය! කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'JiraFailedGetStatuses' => 'ලබා ගත හැකි තත්වයන් ලබා ගැනීමට අපොහොසත් විය! කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'JiraCreateIssueOnNewRisk' => 'අවදානමක් නිර්මාණය වූ විට නව ජිරා ගැටළු නිර්මාණය කිරීමට සරල අවදානම් වලට ඉඩ දෙන්න.',
