    'JiraProjectKeyForNewIssueIsInvalid' => 'නිශ්චිත යතුර සමඟ කිසිදු ව්‍යාපෘතියක් සොයාගත නොහැකි විය!',
    'JiraProjectKeyForNewIssueIsMalformed' => 'නිශ්චිත ව්‍යාපෘති යතුරෙහි වලංගු නොවන අක්ෂර අඩංගු වේ.',
