    'JiraGeneralSynchronizationSettings' => 'සාමාන්‍ය සමමුහුර්ත සැකසුම්',
    
    'JiraSynchronizationConflict' => 'ගැටුම',
    'JiraSynchronizationConflictDescription' => 'පරස්පර ක්ෂේත්‍ර අගයන් මත අවදානම් හෝ ජිරා නිකුතුවේ අනුවාදය භාවිතා කළ යුතු බව තෝරන්න. ජිරා ගැටළුවක් අවදානමකට පැවරීමෙන් පසු පළමු සමමුහුර්තකරණයට එකම තර්කනය අදාළ වේ.',
    'JiraUseRiskValueOnConflict' => 'අවදානම් අගය භාවිතා කරන්න (පෙරනිමිය)',
    'JiraUseIssueValueOnConflict' => 'ජිරා නිකුතුවේ වටිනාකම භාවිතා කරන්න',

    'JiraSynchronizationFields' => 'ක්ෂේත්ර',
    'JiraSynchronizeStatus' => '"තත්වය" සමමුහුර්තකරණය සක්‍රීය කරන්න',
    'JiraSynchronizeStatusSelectionInstructions' => 'කරුණාකර ඔබේ ව්‍යාපෘතිවල වැඩ ප්‍රවාහයන්හි භාවිතා වන ඕනෑම තත්වයකට නිදහසේ සංක්‍රමණය කළ හැකි තත්වයක් තෝරන්න සහ ඔබේ සියලු ව්‍යාපෘති සඳහා ලබා ගත හැකිය.',
    'JiraSynchronizeStatusInstructions' => 'නිශ්චිත තත්ව සංක්‍රාන්ති මත සිදුවිය යුතු දේ තීරණය කරන්න',
