    'Admin' => 'පරිපාලක',
    'AdminRoleDescription' => 'මෙම අවසරය සිම්පල් රිස්ක් හි වින්‍යාසයන්ට ප්‍රවේශය සපයයි. මෙම අවසරය ඇති පරිශීලකයෙකු පද්ධතියේ පරිපාලනමය පරිශීලකයෙකි. "වින්‍යාස කරන්න" මෙනුවේ ඇති ඕනෑම හා සියලු මෙනු වල වෙනස්කම් කිරීමට ඔවුන්ට හැකියාව ඇත. අමතර සක්‍රිය කිරීම සහ අක්‍රිය කිරීම සහ ඒවායේ වින්‍යාසයන් වෙනස් කිරීම සඳහා ද මෙය ඉඩ දෙයි. මෙම අවසරය ලබා දිය යුත්තේ එහි නිරපේක්ෂ අවශ්‍යතාව ඇති අයට පමණි. පරිශීලකයෙකුට මෙම අවසරයට ප්‍රවේශ වූ පසු ඔවුන්ට වෙනත් පරිශීලක ගිණුම් සංස්කරණය කිරීමට ද හැකි වේ.',
