    'JiraProjectForNewIssueIsInvalid' => 'නිශ්චිත හැඳුනුම්පත සමඟ කිසිදු ව්‍යාපෘතියක් සොයාගත නොහැකි විය!',
    'JiraIssueTypeForNewIssueIsRequired' => 'ජිරා නිකුත් කිරීමේ වර්ගය අවශ්‍යයි!',
