    'UserImportFieldsRequired' => 'පරිශීලක නාමයක්, සම්පූර්ණ නම සහ විද්‍යුත් තැපැල් ලිපිනය අවශ්‍ය වේ.',
    'NewUsernameAddedSuccessfully' => '{$username}" පරිශීලක නාමය සහිත නව පරිශීලකයෙකු සාර්ථකව එක් කරන ලදි.',
    'UsernameWasUpdatedSuccessfully' => '${username}" පරිශීලක නාමය ඇති පරිශීලකයා සාර්ථකව යාවත්කාලීන කරන ලදි.',
