    'SSLSecurityCheckWarning' => 'අවවාදයයි: SSL විසින් MITM ප්‍රහාර වළක්වන අතර පහත විකල්ප අක්‍රිය කිරීම ආරක්‍ෂක සැලකිල්ලකි',
