    'EnableSSLCertificateCheckVM' => 'අවදානම් කළමනාකරණය සඳහා SSL සහතික චෙක්පත් සබල කරන්න',
    'DuoToopherRemoved' => 'Duo හට තවදුරටත් SimpleRisk සෘජුවම සහාය දක්වයි. ඒ වෙනුවට, අපි සාමාන්‍ය TOTP සත්‍යාපකයක් වෙත සංක්‍රමණය වී ඇත. කරුණාකර ඔබගේ නව සත්‍යාපකය පහතින් පිහිටුවන්න.',
    'ProtectYourSimpleRiskAccount' => 'ඔබගේ සරල අවදානම් ගිණුම ආරක්ෂා කරන්න',
    '2FADescription' => 'ද්වි-සාධක සත්‍යාපනය ඔබගේ අනන්‍යතාවය තහවුරු කිරීම සඳහා ද්විතියික උපාංගයක් භාවිතා කිරීමෙන් ඔබගේ ගිණුමේ ආරක්ෂාව වැඩි කරයි. මෙය ඔබ හැර අන් කිසිවෙකු ඔබගේ මුරපදය දැන සිටියත්, ඔබගේ ගිණුමට ප්‍රවේශ වීම වළක්වයි.',
    '2FAStep1' => 'පියවර 1 - Google Authenticator වැනි 2FA යෙදුමකින් පහත කේතය පරිලෝකනය කරන්න',
    '2FAStep2' => 'පියවර 2 - සත්‍යාපනය කිරීමට පහත ඔබේ 2FA යෙදුමෙන් කේතය ඇතුළු කරන්න',
