    'EditFailed_RequiredFieldEmpty' => 'සංස්කරණය අසාර්ථක විය, අවශ්‍ය ක්ෂේත්‍රය "{$field}" හිස් විය නොහැක.',
    'EditFailed_FieldNotEditable' => 'සංස්කරණය අසාර්ථක විය, "{$field}" ක්ෂේත්‍රය සංස්කරණය කළ නොහැක.',
    'EditFailed_CustomFieldNeedsCustomization' => 'සංස්කරණය අසාර්ථක විය, අභිරුචි ක්ෂේත්‍ර සංස්කරණය කළ හැක්කේ අභිරුචිකරණ අතිරේකය සක්‍රිය කළ විට පමණි.',
    'EditFailed_InvalidView' => 'සංස්කරණය අසාර්ථක විය, වලංගු නොවන දසුනක් ඉල්ලා ඇත.',
    'FieldUpdated_asset' => '"{$name}" වත්කමේ "{$fieldName}" ක්ෂේත්‍රය "{$user}" පරිශීලකයා විසින් යාවත්කාලීන කරන ලදී.',
    'UpdateSuccess_asset' => '"{$name}" වත්කම "{$user}" පරිශීලකයා විසින් සාර්ථකව යාවත්කාලීන කරන ලදී.',
    'AreYouSureYouWantToDeactivateThisExtra' => 'ඔබට මෙම අතිරේක අක්‍රිය කිරීමට අවශ්‍ය බව විශ්වාසද?',
