    'SettingsMailDesc'                    => 'ප්‍රවාහනය, සත්කාරක, සත්‍යාපනය සහ පිළිතුරු දීම ඇතුළුව පිටතට යන විද්‍යුත් තැපැල් දැනුම්දීම් සඳහා SMTP වින්‍යාසය.',
