    'EncryptionActivationAlreadyRunning' => 'සංකේතන සක්‍රිය කිරීමක් දැනටමත් සිදුවෙමින් පවතී. එය සම්පූර්ණ වන තෙක් රැඳී සිටින්න නැතහොත් ප්‍රතිසාධනය කිරීමට උපස්ථයෙන් ප්‍රතිසාධනය භාවිතා කරන්න.',
