    'EncryptionActivationEnqueueFailed'      => 'සංකේතන සක්‍රිය කිරීමේ කාර්යය පෝලිමේ තැබීමට අසමත් විය. විස්තර සඳහා නිදොස් කිරීමේ ලොගය පරීක්ෂා කරන්න.',
