    'AIProviderNotConfiguredWarning' => 'AI සැපයුම්කරු වින්‍යාස කර නොමැත. ඔබ සැපයුම්කරු වින්‍යාස පටිත්තෙහි සැපයුම්කරු සහ API යතුර සකසන තුරු සජීවී ප්‍රතිඵල නිපදවීමට නොහැකිය.',
