    'NotFrameworkDescription' => 'පහත විජට් එක Secure Controls Framework (SCF) පැතුරුම්පතෙහි ඇති සියලුම ශීර්ෂයන් පෙන්වයි. රාමු නොවන දත්ත අඩංගු තීරු මොනවාද යන්න තෝරා ගැනීමට එය භාවිතා කරන්න.',
    'Note' => 'සටහන',
