    'FailedToFetchCVEInformation' => 'CVE තොරතුරු ලබා ගැනීමට අපොහොසත් විය. කරුණාකර CVE ID පරීක්ෂා කර නැවත උත්සාහ කරන්න.',
    'ComplianceDashboard' => 'අනුකූලතා උපකරණ පුවරුව',
