    'ComplianceDashboardDescription' => 'මෙම ප්‍රස්ථාරයේ එක් එක් රාමුවේ ඇති පාලන ගණන කොළ පැහැයෙන් ද අසාර්ථක පාලන රතු පැහැයෙන් ද දැක්වේ.',
    'PassingControls' => 'සමත් පාලන',
