    'BUChartCrossUnitNote' => 'සටහන: බහු BUs දක්වා විහිදෙන කණ්ඩායම් සඳහා පවරා ඇති අවදානම් එක් එක් කාණ්ඩයේ ගණනය කෙරේ.',
