    'SoaAppendixJustifications' => 'උපග්‍රන්ථය A — සාධාරණීකරණයන්',
    'SoaAppendixRemediation' => 'උපග්‍රන්ථය R — ප්‍රතිකර්ම සැලසුම්',
    // Appendix E carries the WORDING of each test's evidence requirement. The row
