    'SoaRequiredEvidenceSupplied' => 'අවශ්‍ය සාක්ෂි සපයා ඇත',
    'SoaRequiredEvidenceNotSupplied' => 'අවශ්‍ය සාක්ෂි සපයා නැත',
    // The one scheduling fact the SoA prints: the soonest date any of a control's
