    'SoaEvidencePolicy' => 'ප්රතිපත්ති',
    'SoaEvidenceStandard' => 'සම්මත',
    'SoaEvidenceProcedure' => 'ක්රියා පටිපාටිය',
    'SoaEvidenceGuideline' => 'මාර්ගෝපදේශය',
