    'SoaJustifiedByRiskAssessment' => 'සංවිධානයේ තොරතුරු ආරක්ෂක අවදානම් තක්සේරුව මගින් තීරණය කරනු ලැබේ. සම්බන්ධිත අවදානම්: {risks}.',

    // The Implemented column. DERIVED from maturity and the last test result on
