    'SoaImplemented' => 'ක්‍රියාත්මක කරන ලදී',
    'SoaImplementedPartial' => 'අර්ධ',

    // The cover block.
    'SoaGeneratedOn' => 'ජනනය කරන ලද්දේ',
    'SoaExcludedCount' => 'බැහැර කර ඇත',

    // The prompt shown when the framework has never been given the two cover
