    'SoaChooseFrameworkHint' => 'අදාළත්වය පිළිබඳ ප්‍රකාශයක් වරකට එක් රාමුවක් පිළිබඳව ලියා ඇත.',
    // The picker has a roster but nothing in it. Distinct from "this framework
